#!/usr/bin/env python3
"""
ekf_odom_fusion_node.py

ROS2 node that fuses wheel odometry and IMU using a simple Extended Kalman Filter (EKF),
publishes fused odometry on /odom_fused (nav_msgs/Odometry) and broadcasts odom -> base_link tf.

Assumptions:
 - Wheel odometry (pose/twist) is published on /odom_raw (nav_msgs/Odometry)
 - IMU is published on /imu/data (sensor_msgs/Imu)

How it works (brief):
 - State: [x, y, theta, v]
 - Predict: propagate using last velocity v and angular rate w
 - Update: use odom linear velocity and IMU angular velocity / orientation as measurements

Notes:
 - Remap topics to match your setup if needed.
 - Disable other odom->base_link broadcasters to avoid TF conflicts (e.g. robot_state_publisher, other odom nodes).
 - Tune process and measurement noise covariances for your robot.

Author: Generated by ChatGPT (example template). Use and modify for your robot.
"""

import rclpy
from rclpy.node import Node
from rclpy.qos import QoSProfile, QoSReliabilityPolicy, QoSHistoryPolicy
from nav_msgs.msg import Odometry
from sensor_msgs.msg import Imu
from geometry_msgs.msg import TransformStamped
import numpy as np
import math
import time

from tf_transformations import euler_from_quaternion, quaternion_from_euler
import tf2_ros


def quat_to_yaw(qx, qy, qz, qw):
    # safe conversion
    _, _, yaw = euler_from_quaternion([qx, qy, qz, qw])
    return yaw


class EKFOdomFusion(Node):
    def __init__(self):
        super().__init__('ekf_odom_fusion')

        qos = QoSProfile(depth=10)
        qos.reliability = QoSReliabilityPolicy.RELIABLE
        qos.history = QoSHistoryPolicy.KEEP_LAST

        # Parameters (tweak)
        self.declare_parameter('odom_topic', '/odom_raw')
        self.declare_parameter('imu_topic', '/imu/data')
        self.declare_parameter('fused_odom_topic', '/odom')
        self.declare_parameter('base_frame', 'base_link')
        self.declare_parameter('odom_frame', 'odom')
        self.declare_parameter('publish_tf', True)
        self.declare_parameter('publish_rate', 50.0)
        self.declare_parameter('use_imu_orientation', True)

        # Noise parameters
        self.declare_parameter('process_noise_cov', [1e-3, 1e-3, 1e-4, 1e-2])
        self.declare_parameter('odom_linear_meas_cov', 1e-2)
        self.declare_parameter('imu_angular_meas_cov', 1e-3)
        self.declare_parameter('imu_orientation_meas_cov', 1e-2)

        self.odom_topic = self.get_parameter('odom_topic').get_parameter_value().string_value
        self.imu_topic = self.get_parameter('imu_topic').get_parameter_value().string_value
        self.fused_odom_topic = self.get_parameter('fused_odom_topic').get_parameter_value().string_value
        self.base_frame = self.get_parameter('base_frame').get_parameter_value().string_value
        self.odom_frame = self.get_parameter('odom_frame').get_parameter_value().string_value
        self.publish_tf = self.get_parameter('publish_tf').get_parameter_value().bool_value
        self.publish_rate = self.get_parameter('publish_rate').get_parameter_value().double_value
        self.use_imu_orientation = self.get_parameter('use_imu_orientation').get_parameter_value().bool_value

        pn = self.get_parameter('process_noise_cov').get_parameter_value().double_array_value
        self.Q = np.diag(pn)  # process noise diag for [x,y,theta,v]
        self.odom_linear_meas_cov = self.get_parameter('odom_linear_meas_cov').get_parameter_value().double_value
        self.imu_angular_meas_cov = self.get_parameter('imu_angular_meas_cov').get_parameter_value().double_value
        self.imu_orientation_meas_cov = self.get_parameter('imu_orientation_meas_cov').get_parameter_value().double_value

        # EKF state and covariance
        # state vector x = [x, y, theta, v]
        self.x = np.zeros((4, 1), dtype=float)
        self.P = np.eye(4) * 1e-2

        # last timestamp
        self.last_time = None

        # last measurements
        self.last_odom_v = 0.0
        self.last_odom_w = 0.0
        self.last_imu_w = 0.0
        self.last_imu_yaw = None

        # Publishers and subscribers
        self.odom_sub = self.create_subscription(Odometry, self.odom_topic, self.odom_callback, qos)
        self.imu_sub = self.create_subscription(Imu, self.imu_topic, self.imu_callback, qos)

        self.odom_pub = self.create_publisher(Odometry, self.fused_odom_topic, 10)

        if self.publish_tf:
            self.tf_broadcaster = tf2_ros.TransformBroadcaster(self)

        timer_period = 1.0 / float(self.publish_rate)
        self.timer = self.create_timer(timer_period, self.timer_callback)

        self.get_logger().info('EKF Odom Fusion node started: odom=%s imu=%s -> fused=%s' % (self.odom_topic, self.imu_topic, self.fused_odom_topic))

    # ---------------------------
    # Callbacks
    # ---------------------------
    def odom_callback(self, msg: Odometry):
        # Update last odom measurements
        try:
            v = msg.twist.twist.linear.x
            w = msg.twist.twist.angular.z
        except Exception:
            v = 0.0
            w = 0.0
        self.last_odom_v = float(v)
        self.last_odom_w = float(w)

        # If odom contains pose, we could optionally use it as measurement (not used by default)
        # Keep timestamp
        self.last_odom_time = self.to_sec(msg.header.stamp)

    def imu_callback(self, msg: Imu):
        # angular velocity z
        self.last_imu_w = float(msg.angular_velocity.z)
        # orientation yaw
        q = msg.orientation
        if not (math.isclose(q.x, 0.0) and math.isclose(q.y, 0.0) and math.isclose(q.z, 0.0) and math.isclose(q.w, 0.0)):
            yaw = quat_to_yaw(q.x, q.y, q.z, q.w)
            self.last_imu_yaw = float(yaw)
        self.last_imu_time = self.to_sec(msg.header.stamp)

    # ---------------------------
    # Timer: run predict + update loop at publish_rate
    # ---------------------------
    def timer_callback(self):
        now = self.get_clock().now().to_msg()
        t = self.to_sec(now.stamp)
        if self.last_time is None:
            self.last_time = t
            return
        dt = t - self.last_time
        if dt <= 0:
            return
        self.last_time = t

        # Use IMU angular velocity primarily (if available), else odom angular
        w_meas = self.last_imu_w if self.last_imu_w is not None else self.last_odom_w
        v_meas = self.last_odom_v

        # Predict step
        self.ekf_predict(v_meas, w_meas, dt)

        # Update step: velocity measurement
        self.ekf_update_velocity(v_meas)

        # Update step: angular rate from IMU
        if not math.isnan(self.last_imu_w):
            self.ekf_update_yaw_rate(self.last_imu_w)

        # Optionally update orientation from IMU (absolute yaw)
        if self.use_imu_orientation and self.last_imu_yaw is not None:
            self.ekf_update_yaw_absolute(self.last_imu_yaw)

        # Publish fused odometry and tf
        self.publish_fused_odom(t)

    # ---------------------------
    # EKF functions
    # ---------------------------
    def ekf_predict(self, v, w, dt):
        # State vector: [x, y, theta, v]
        x, y, theta, vel = self.x.flatten()

        # control: v (linear) and w (angular)
        # simple bicycle/differential drive model
        if abs(w) < 1e-6:
            dx = v * math.cos(theta) * dt
            dy = v * math.sin(theta) * dt
            dtheta = 0.0
        else:
            dtheta = w * dt
            dx = v * math.cos(theta) * dt
            dy = v * math.sin(theta) * dt

        # Predict state
        x_pred = x + dx
        y_pred = y + dy
        theta_pred = self.normalize_angle(theta + dtheta)
        v_pred = v  # assume velocity follow measurement

        self.x = np.array([[x_pred], [y_pred], [theta_pred], [v_pred]])

        # Jacobian F = df/dx
        F = np.eye(4)
        F[0, 2] = -v * math.sin(theta) * dt
        F[0, 3] = math.cos(theta) * dt
        F[1, 2] = v * math.cos(theta) * dt
        F[1, 3] = math.sin(theta) * dt
        F[2, 2] = 1.0
        F[3, 3] = 1.0

        # Process noise Q (already diag)
        # Add small angle noise scaling
        Qk = self.Q * max(dt, 1e-3)

        # Update covariance
        self.P = F.dot(self.P).dot(F.T) + Qk

    def ekf_update_velocity(self, v_meas):
        # Measurement z = v (linear velocity)
        H = np.zeros((1, 4))
        H[0, 3] = 1.0
        z = np.array([[v_meas]])
        R = np.array([[self.odom_linear_meas_cov]])

        y = z - H.dot(self.x)
        S = H.dot(self.P).dot(H.T) + R
        K = self.P.dot(H.T).dot(np.linalg.inv(S))
        self.x = self.x + K.dot(y)
        self.P = (np.eye(4) - K.dot(H)).dot(self.P)

    def ekf_update_yaw_rate(self, w_meas):
        # We don't have yaw rate in the state directly, but theta_dot ~ w_meas
        # Approximate with finite difference: use relation theta_dot = w_meas
        # We update theta by integrating w_meas for a small correction
        # Equivalent to adding pseudo-measurement for theta_dot; here we correct theta using small step
        # Simpler: treat measured w as measurement of dtheta/dt and correct theta via innovation
        # We'll form H that maps state to theta_dot: theta_dot = 0 (not in state) -> approximate via difference
        # Instead, do a low-weight update to theta using w_meas*dt
        # For stability, skip explicit Kalman update for yaw rate; rely on predict+absolute yaw update
        return

    def ekf_update_yaw_absolute(self, yaw_meas):
        # Measurement z = yaw (absolute)
        H = np.zeros((1, 4))
        H[0, 2] = 1.0
        z = np.array([[self.normalize_angle(yaw_meas)]])
        R = np.array([[self.imu_orientation_meas_cov]])

        # Innovation must handle angle wrapping
        y = z - H.dot(self.x)
        y[0, 0] = self.normalize_angle(float(y[0, 0]))

        S = H.dot(self.P).dot(H.T) + R
        K = self.P.dot(H.T).dot(np.linalg.inv(S))
        self.x = self.x + K.dot(y)
        self.P = (np.eye(4) - K.dot(H)).dot(self.P)

    # ---------------------------
    # Publish fused odom and tf
    # ---------------------------
    def publish_fused_odom(self, stamp_sec):
        odom_msg = Odometry()
        odom_msg.header.stamp.sec = int(stamp_sec)
        odom_msg.header.stamp.nanosec = int((stamp_sec - int(stamp_sec)) * 1e9)
        odom_msg.header.frame_id = self.odom_frame
        odom_msg.child_frame_id = self.base_frame

        x, y, theta, v = self.x.flatten()

        # pose
        q = quaternion_from_euler(0.0, 0.0, float(theta))
        odom_msg.pose.pose.position.x = float(x)
        odom_msg.pose.pose.position.y = float(y)
        odom_msg.pose.pose.position.z = 0.0
        odom_msg.pose.pose.orientation.x = q[0]
        odom_msg.pose.pose.orientation.y = q[1]
        odom_msg.pose.pose.orientation.z = q[2]
        odom_msg.pose.pose.orientation.w = q[3]

        # twist
        odom_msg.twist.twist.linear.x = float(v)
        # angular z from imu preferred
        angz = self.last_imu_w if self.last_imu_w is not None else self.last_odom_w
        odom_msg.twist.twist.angular.z = float(angz)

        # Covariances (fill diagonals)
        # pose covariance: x,y,theta -> positions
        pose_cov = [0.0] * 36
        pose_cov[0] = self.P[0, 0]  # x
        pose_cov[7] = self.P[1, 1]  # y
        pose_cov[35] = self.P[2, 2]  # yaw
        odom_msg.pose.covariance = pose_cov

        twist_cov = [0.0] * 36
        twist_cov[0] = self.P[3, 3]  # vx var
        twist_cov[35] = self.imu_angular_meas_cov
        odom_msg.twist.covariance = twist_cov

        self.odom_pub.publish(odom_msg)

        if self.publish_tf:
            t = TransformStamped()
            t.header.stamp = odom_msg.header.stamp
            t.header.frame_id = self.odom_frame
            t.child_frame_id = self.base_frame
            t.transform.translation.x = float(x)
            t.transform.translation.y = float(y)
            t.transform.translation.z = 0.0
            t.transform.rotation.x = q[0]
            t.transform.rotation.y = q[1]
            t.transform.rotation.z = q[2]
            t.transform.rotation.w = q[3]

            # broadcast
            try:
                self.tf_broadcaster.sendTransform(t)
            except Exception as e:
                self.get_logger().warn('TF broadcast failed: %s' % str(e))

    # ---------------------------
    # Utilities
    # ---------------------------
    @staticmethod
    def to_sec(t):
        # t is builtin time msg or rclpy.time.msg
        try:
            return t.sec + t.nanosec * 1e-9
        except Exception:
            # if it's rclpy Time msg maybe
            return float(t.sec) + float(t.nanosec) * 1e-9

    @staticmethod
    def normalize_angle(a):
        a = float(a)
        return math.atan2(math.sin(a), math.cos(a))


def main(args=None):
    rclpy.init(args=args)
    node = EKFOdomFusion()
    try:
        rclpy.spin(node)
    except KeyboardInterrupt:
        pass
    finally:
        node.destroy_node()
        rclpy.shutdown()


if __name__ == '__main__':
    main()
